package com.combotags;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.plugins.banktags.BankTag;

/**
 * Membership filter for a CORE/built-in layout tab that hosts combo cells.
 *
 * <p>RuneLite combines this with the tab's real tag via OR (see {@code BankTagsPlugin.buildSearchFilterBankTag}),
 * so it can only ADD items to the tab, never hide tagged ones. We exploit that: combo member items are NOT
 * individually tagged, and this tag makes only the currently-resolved OWNED winners pass the bank filter so
 * they render as real, withdrawable widgets at their cells. Non-winner members and leftover placeholders are
 * never in the set, so RuneLite never pulls them into the tab and never auto-floats them.
 *
 * <p>The winner set is recomputed live from the bank by {@code maintainComboCoreTab} on every bank change and
 * swapped in here; {@link #contains(int)} runs in the bank-build filter, so it must be O(1).
 */
public final class ComboBankTag implements BankTag
{
	private volatile Set<Integer> ownedWinners = Collections.emptySet();

	/** Replaces the set of owned-winner item ids that should pass the tab's bank filter. */
	public void setOwnedWinners(Set<Integer> winners)
	{
		this.ownedWinners = winners == null ? Collections.emptySet() : new HashSet<>(winners);
	}

	@Override
	public boolean contains(int itemId)
	{
		return ownedWinners.contains(itemId);
	}
}

package com.combotags;

/**
 * A collapsible category in the side panel that groups combo tags (e.g. "Melee"). Combos reference it
 * by name via {@link ComboGroup#category}. Persisted as JSON by {@link ComboStore}.
 */
public class ComboCategory
{
	public String name = "";
	public boolean collapsed = false;
	public int color = ComboGroup.DEFAULT_COLOR; // group color; new combos created into this group inherit it
	public boolean hideHighlight = false; // true = combos in this group don't draw the bank overlay highlight (inherited like color)

	public ComboCategory()
	{
	}

	public ComboCategory(String name)
	{
		this.name = name;
	}
}

package com.combotags;

import com.google.gson.Gson;
import java.awt.Toolkit;
import java.awt.datatransfer.Clipboard;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Share-string codec for combos. A single combo or a whole category (its combos bundled with it) is encoded
 * as a short prefixed token — {@code combotag:v1:<base64 json>} / {@code combogroup:v1:<base64 json>} — that
 * round-trips through {@link Gson} (the same serialization {@link ComboStore} persists). Base64 keeps it a
 * single opaque token with no whitespace/braces to mangle on copy-paste.
 */
@Slf4j
public final class ComboCodec
{
	public static final String COMBO_PREFIX = "combotag:v1:";
	public static final String GROUP_PREFIX = "combogroup:v1:";

	// A share token: a prefix plus its trailing base64 run. We split on the prefix BOUNDARY first (below) before
	// matching, because the prefix letters ("combogroup"/"combotag") are themselves valid base64 — so a greedy
	// run would otherwise swallow a directly-appended next prefix. The ':' in ":v1:" can't occur in base64, so
	// the boundary is unambiguous and tokens separate even when concatenated with no whitespace.
	private static final Pattern TOKEN_PATTERN = Pattern.compile(
		"(?:" + Pattern.quote(COMBO_PREFIX) + "|" + Pattern.quote(GROUP_PREFIX) + ")[A-Za-z0-9+/=]+");
	// Zero-width split point right before each prefix, so back-to-back tokens become separate pieces.
	private static final Pattern TOKEN_BOUNDARY = Pattern.compile(
		"(?=" + Pattern.quote(COMBO_PREFIX) + "|" + Pattern.quote(GROUP_PREFIX) + ")");

	/** A category plus the combos filed under it, for a whole-group export. */
	public static final class Bundle
	{
		public ComboCategory category;
		public List<ComboGroup> combos;
	}

	private ComboCodec()
	{
	}

	public static String exportCombo(Gson gson, ComboGroup g)
	{
		return COMBO_PREFIX + encode(gson.toJson(g));
	}

	public static String exportGroup(Gson gson, Bundle bundle)
	{
		return GROUP_PREFIX + encode(gson.toJson(bundle));
	}

	public static boolean isComboString(String s)
	{
		String t = s == null ? "" : s.trim();
		return t.startsWith(COMBO_PREFIX) || t.startsWith(GROUP_PREFIX);
	}

	public static boolean isGroupString(String s)
	{
		return s != null && s.trim().startsWith(GROUP_PREFIX);
	}

	/**
	 * Every combo/group share token found in arbitrary text, in order. Handles tokens appended back-to-back or
	 * separated by headers/blank lines (e.g. a pastebin holding several groups) and ignores surrounding text.
	 */
	public static List<String> extractTokens(String text)
	{
		List<String> out = new ArrayList<>();
		if (text == null)
		{
			return out;
		}
		// Split before each prefix (separates back-to-back tokens), then take the leading token of each piece
		// (any trailing header/whitespace within a piece stops the base64 run).
		for (String piece : TOKEN_BOUNDARY.split(text))
		{
			Matcher m = TOKEN_PATTERN.matcher(piece);
			if (m.lookingAt())
			{
				out.add(m.group());
			}
		}
		return out;
	}

	/** Decodes a single-combo string; returns a normalized {@link ComboGroup}, or null if invalid. */
	public static ComboGroup importCombo(Gson gson, String s)
	{
		String t = s == null ? "" : s.trim();
		if (!t.startsWith(COMBO_PREFIX))
		{
			return null;
		}
		try
		{
			ComboGroup g = gson.fromJson(decode(t.substring(COMBO_PREFIX.length())), ComboGroup.class);
			if (g == null || g.name == null || g.name.isEmpty())
			{
				return null;
			}
			g.normalize();
			return g;
		}
		catch (Exception ex)
		{
			log.warn("failed to parse combo import string", ex);
			return null;
		}
	}

	/** Decodes a whole-group string; returns its {@link Bundle}, or null if invalid. */
	public static Bundle importGroup(Gson gson, String s)
	{
		String t = s == null ? "" : s.trim();
		if (!t.startsWith(GROUP_PREFIX))
		{
			return null;
		}
		try
		{
			Bundle b = gson.fromJson(decode(t.substring(GROUP_PREFIX.length())), Bundle.class);
			if (b == null || b.category == null || b.category.name == null || b.category.name.isEmpty())
			{
				return null;
			}
			if (b.combos == null)
			{
				return null;
			}
			b.combos.forEach(ComboGroup::normalize);
			return b;
		}
		catch (Exception ex)
		{
			log.warn("failed to parse combo group import string", ex);
			return null;
		}
	}

	public static void toClipboard(String s)
	{
		Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
		clipboard.setContents(new StringSelection(s), null);
	}

	public static String fromClipboard()
	{
		try
		{
			Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
			Object data = clipboard.getData(DataFlavor.stringFlavor);
			return data == null ? null : data.toString();
		}
		catch (Exception ex)
		{
			return null;
		}
	}

	private static String encode(String json)
	{
		return Base64.getEncoder().encodeToString(json.getBytes(StandardCharsets.UTF_8));
	}

	private static String decode(String token)
	{
		return new String(Base64.getDecoder().decode(token.trim()), StandardCharsets.UTF_8);
	}
}

package com.combotags;

import java.util.ArrayList;
import java.util.List;
import java.util.function.BiFunction;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Shared codec for the combo-cell slot config values ({@code comboslots_<tab>}, see {@link ComboSlots}),
 * stored as a CSV of {@code index:value} rows. Centralizes the {@link Text#fromCSV}/{@code split(":")}/
 * {@code parseInt} parse-serialize pair so a format change lands in one place. Values live under
 * {@link ComboTagsPlugin#CONFIG_GROUP}.
 */
public final class ComboCsv
{
	private ComboCsv()
	{
	}

	/**
	 * Reads a config CSV value, splitting each entry on {@code :} and invoking {@code parser} with the parsed
	 * int index and the full parts array. Entries with fewer than two parts or a non-integer index are skipped,
	 * as is a {@code null} parser result (so the parser can reject a malformed value). Order is preserved.
	 */
	public static <T> List<T> read(ConfigManager configManager, String key, BiFunction<Integer, String[], T> parser)
	{
		List<T> out = new ArrayList<>();
		String csv = configManager.getConfiguration(ComboTagsPlugin.CONFIG_GROUP, key);
		if (csv == null || csv.isEmpty())
		{
			return out;
		}
		for (String entry : Text.fromCSV(csv))
		{
			String[] parts = entry.split(":");
			if (parts.length < 2)
			{
				continue;
			}
			int index;
			try
			{
				index = Integer.parseInt(parts[0].trim());
			}
			catch (NumberFormatException ignored)
			{
				continue; // malformed index → skip
			}
			T value = parser.apply(index, parts);
			if (value != null)
			{
				out.add(value);
			}
		}
		return out;
	}

	/** Writes pre-formatted {@code index:value} rows to a config CSV value; unsets the key when empty. */
	public static void write(ConfigManager configManager, String key, List<String> rows)
	{
		if (rows.isEmpty())
		{
			configManager.unsetConfiguration(ComboTagsPlugin.CONFIG_GROUP, key);
			return;
		}
		configManager.setConfiguration(ComboTagsPlugin.CONFIG_GROUP, key, Text.toCSV(rows));
	}
}

package com.combotags;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * A combo gear group: a named, ordered list of member base item ids plus display/ranking settings.
 * Persisted as JSON by {@link ComboStore}. The {@link #name} is the canonical id, bracketed
 * (e.g. {@code [Melee Helm]}); the member list order IS the priority order.
 */
public class ComboGroup
{
	public static final int DEFAULT_COLOR = 0xFFFF00;

	public String name = "";
	public List<Integer> members = new ArrayList<>(); // base item ids, highest priority first (manual order)
	public int color = DEFAULT_COLOR;                   // RGB
	public String category = "";                         // optional category/group name this combo belongs to
	// base id -> that member's variant ids in priority order. The TOP entry is the variant this combo "serves"
	// (shown in the panel/ghost/icon); during resolution the highest-priority OWNED variant wins (lets you
	// prefer a specific recolor/version when you hold several). Empty = default order (functional item first).
	public Map<Integer, List<Integer>> variantOrder = new HashMap<>();
	public int icon = 0;                                 // favorite display item id (0 = use the top member)
	public boolean hideHighlight = false;                // true = don't draw the bank overlay highlight for this combo's cell

	public ComboGroup()
	{
	}

	public ComboGroup(String name)
	{
		this.name = name;
	}

	/**
	 * The item id to display as this combo's icon (side-panel row + the bank "nothing owned" ghost): the
	 * favorite {@link #icon} if set and still belongs to a member, otherwise the top member's chosen variant,
	 * or {@code -1} when the combo is empty.
	 */
	public int displayIconId()
	{
		if (icon != 0 && members.contains(ItemIndex.statBaseOfCanon(icon)))
		{
			return icon;
		}
		if (members.isEmpty())
		{
			return -1;
		}
		return servedVariant(members.get(0));
	}

	/**
	 * The variant of {@code base} this combo "serves" (the version shown in the panel, group icon, and ghost):
	 * the top of the member's stored priority order if it has one, else the first of its default variant options
	 * — which lists the functional item ahead of a variation-mapped "(damaged)" base. Static item lookups only,
	 * so it is safe off the client thread.
	 */
	public int servedVariant(int base)
	{
		List<Integer> order = variantOrder == null ? null : variantOrder.get(base);
		if (order != null && !order.isEmpty())
		{
			return order.get(0);
		}
		List<Integer> opts = ItemIndex.variants(base); // equippable variants in default order
		return opts.isEmpty() ? base : opts.get(0);
	}

	/** The member base that owns the favorite icon, or {@code -1} if there's no (valid) favorite. */
	public int favoriteOwner()
	{
		if (icon == 0)
		{
			return -1;
		}
		int owner = ItemIndex.statBaseOfCanon(icon);
		return members.contains(owner) ? owner : -1;
	}

	/** Ensures collections/fields are non-null after Gson deserialization. */
	public void normalize()
	{
		if (name == null)
		{
			name = "";
		}
		if (members == null)
		{
			members = new ArrayList<>();
		}
		if (variantOrder == null)
		{
			variantOrder = new HashMap<>();
		}
		if (category == null)
		{
			category = "";
		}
	}

	/** Wraps a user-entered name in brackets and strips characters that would break our CSV/JSON keys. */
	public static String bracket(String raw)
	{
		String s = raw == null ? "" : raw.replaceAll("[\\[\\]:,]", "").trim();
		return "[" + s + "]";
	}
}

package com.combotags;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the combo "smart cell" highlights over a built-in bank tag layout. The cell index IS the core layout
 * position, so {@link ComboTagsPlugin#getComboCellGroups} gives each box's grid slot. RuneLite renders the
 * winner widget and the unowned ghost (its own faded layout placeholder); this overlay only draws the box.
 */
public class ComboOverlay extends Overlay
{
	private final ComboTagsPlugin plugin;
	private final Client client;
	private final ComboTagsConfig config;

	ComboOverlay(ComboTagsPlugin plugin, Client client, ComboTagsConfig config)
	{
		this.plugin = plugin;
		this.client = client;
		this.config = config;
		drawAfterLayer(ComponentID.BANK_ITEM_CONTAINER);
		setLayer(OverlayLayer.MANUAL);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.comboHighlightStyle() == ComboTagsConfig.ComboHighlight.NONE)
		{
			return null;
		}
		String tag = plugin.getCurrentComboTag();
		if (tag == null)
		{
			return null;
		}
		Map<Integer, String> comboCellGroups = plugin.getComboCellGroups(tag);
		if (comboCellGroups.isEmpty())
		{
			return null;
		}
		Widget bankItemContainer = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		if (bankItemContainer == null)
		{
			return null;
		}

		int scrollY = bankItemContainer.getScrollY();
		Point canvasLocation = bankItemContainer.getCanvasLocation();

		int yOffset = 0;
		Widget widget = bankItemContainer;
		while (widget.getParent() != null)
		{
			yOffset += widget.getRelativeY();
			widget = widget.getParent();
		}

		Rectangle bankItemArea = new Rectangle(canvasLocation.getX() + 51 - 6, yOffset,
			bankItemContainer.getWidth() - 51 + 6, bankItemContainer.getHeight());
		graphics.clip(bankItemArea);

		// When RuneLite is dragging the cell's item widget, offset the highlight by the same amount so it
		// follows the item under the cursor instead of staying behind at the cell's grid slot.
		Widget draggedWidget = client.getDraggedWidget();
		int draggedIndex = (draggedWidget != null && draggedWidget.getId() == ComponentID.BANK_ITEM_CONTAINER)
			? draggedWidget.getIndex() : -1;

		ComboTagsConfig.ComboHighlight style = config.comboHighlightStyle();
		for (Map.Entry<Integer, String> cell : comboCellGroups.entrySet())
		{
			if (plugin.isComboHighlightHidden(cell.getValue()))
			{
				continue; // this combo's highlight is turned off — render the item but draw no box/dot/etc.
			}
			int index = cell.getKey();
			int dragDeltaX = 0;
			int dragDeltaY = 0;
			if (index == draggedIndex)
			{
				dragDeltaX = client.getMouseCanvasPosition().getX() - plugin.comboDragPressX;
				dragDeltaY = client.getMouseCanvasPosition().getY() - plugin.comboDragPressY;
				dragDeltaY += scrollY - plugin.comboDragPressScroll;
			}
			int x = ComboTagsPlugin.getXForIndex(index) + canvasLocation.getX() + dragDeltaX;
			int y = ComboTagsPlugin.getYForIndex(index) + yOffset - scrollY + dragDeltaY;
			if (y + ComboTagsPlugin.BANK_ITEM_HEIGHT > bankItemArea.getMinY() && y < bankItemArea.getMaxY())
			{
				drawComboHighlight(graphics, style, plugin.getComboColor(cell.getValue()), x, y, bankItemArea);
			}
		}
		return null;
	}

	/** Draws one combo cell's highlight in the configured style, at the cell's top-left item position (x, y). */
	private void drawComboHighlight(Graphics2D graphics, ComboTagsConfig.ComboHighlight style, Color color,
		int x, int y, Rectangle clip)
	{
		int left = x - 2;
		int top = Math.max(y - 2, (int) clip.getMinY()); // clamp so a partially-scrolled cell isn't off-screen
		int bottom = y + ComboTagsPlugin.BANK_ITEM_HEIGHT;
		int width = ComboTagsPlugin.BANK_ITEM_WIDTH;
		switch (style)
		{
			case OUTLINE:
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
				graphics.setColor(color);
				// 2px stroke so the box reads as boldly as the underline (and matches owned vs ghost cells,
				// which both draw this same outline on top of RuneLite's render).
				java.awt.Stroke oldStroke = graphics.getStroke();
				graphics.setStroke(new java.awt.BasicStroke(2f));
				graphics.drawRect(left, top, width, bottom - top);
				graphics.setStroke(oldStroke);
				break;
			case DOT:
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
				graphics.setColor(color);
				int dot = 7;
				graphics.fillOval(left, top, dot, dot);
				break;
			case UNDERLINE:
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
				graphics.setColor(color);
				int lineWidth = (int) (width * 0.8);
				graphics.fillRect(left + (width - lineWidth) / 2, bottom - 2, lineWidth, 2);
				break;
			case BACKGROUND:
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.25f));
				graphics.setColor(color);
				graphics.fillRect(left, top, width, bottom - top);
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1f));
				break;
			default:
				break;
		}
	}
}

package com.combotags;

import java.awt.BorderLayout;
import java.awt.Color;
