	/**
	 * A ⚠ badge for a category header when two or more of its combos contain the same item, or {@code null}
	 * when there's no overlap. A contested item can't belong to a single cell, so it is excluded from every
	 * combo in the group — no cell shows, claims, or highlights it. The tooltip names the affected item(s),
	 * resolved on the client thread.
	 */
	private JLabel buildCategoryConflictWarning(String categoryName, List<ComboGroup> all)
	{
		List<Integer> shared = sharedMemberBases(categoryName, all);
		if (shared.isEmpty())
		{
			return null;
		}
		JLabel warn = new JLabel("⚠");
		warn.setForeground(WARNING_COLOR);
		// Tooltip is set asynchronously (after rebuild's clearTooltips sweep), so it must honor the config itself.
		if (!plugin.config.disablePanelTooltips())
		{
			warn.setToolTipText("<html>Two combos in this group share an item, so it is <b>not assigned to any"
				+ "<br>combo cell</b> (no cell will show, claim, or highlight it).</html>");
			// Enrich the tooltip with the actual item name(s); getItemComposition must run on the client thread.
			plugin.clientThread.invokeLater(() -> {
				StringBuilder names = new StringBuilder();
				for (int base : shared)
				{
					if (names.length() > 0)
					{
						names.append(", ");
					}
					names.append(plugin.itemManager.getItemComposition(base).getName());
				}
				String tip = "<html><b>Not assigned (shared by multiple combos):</b> " + htmlEscape(names.toString())
					+ "<br>These items appear in more than one combo in this group, so no combo cell"
					+ "<br>will show, claim, or highlight them. Keep an item in just one combo to use it.</html>";
				SwingUtilities.invokeLater(() -> warn.setToolTipText(tip));
			});
		}
		return warn;
	}

	/** Member base ids that appear in two or more of a category's combos (compared at the canonical base). */
	private List<Integer> sharedMemberBases(String categoryName, List<ComboGroup> all)
	{
		Map<Integer, Integer> counts = new HashMap<>(); // canonical base id -> number of combos containing it
		for (ComboGroup g : all)
		{
			if (!categoryName.equals(g.category))
			{
				continue;
			}
			Set<Integer> seen = new HashSet<>(); // a single combo listing an item twice must not self-conflict
			for (int base : g.members)
			{
				int canon = ItemIndex.canonicalBase(base);
				if (seen.add(canon))
				{
					counts.merge(canon, 1, Integer::sum);
				}
			}
		}
		List<Integer> shared = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			if (e.getValue() >= 2)
			{
				shared.add(e.getKey());
			}
		}
		return shared;
	}

	/** Toggles the bank highlight for a whole group, cascading the flag to every combo filed under it. */
	private void toggleCategoryHighlight(ComboCategory cat)
	{
		boolean hide = !cat.hideHighlight;
		cat.hideHighlight = hide;
		ComboStore.upsertCategory(plugin.configManager, plugin.gson, cat);
		// Apply to every member in one parse + one save (mirrors pickCategoryColor's cascade).
		List<ComboGroup> all = ComboStore.all(plugin.configManager, plugin.gson);
		boolean changed = false;
		for (ComboGroup g : all)
		{
			if (cat.name.equals(g.category) && g.hideHighlight != hide)
			{
				g.hideHighlight = hide;
				changed = true;
			}
		}
		if (changed)
		{
			ComboStore.save(plugin.configManager, plugin.gson, all);
		}
		rebuild();
	}

	private void pickCategoryColor(ComboCategory cat, Component anchor)
	{
		net.runelite.client.ui.components.colorpicker.RuneliteColorPicker picker =
			plugin.colorPickerManager.create(
				javax.swing.SwingUtilities.getWindowAncestor(this), new Color(cat.color), cat.name + " color", false);
		placePickerNear(picker, anchor);
		picker.setOnClose(chosen -> {
			// Remember the group color (new combos inherit it) and apply it to every current member.
			cat.color = chosen.getRGB();
			ComboStore.upsertCategory(plugin.configManager, plugin.gson, cat);
			// Recolor every member in one parse + one save (not an upsert-per-member, which re-parsed and
			// rewrote the whole combos JSON for each).
			List<ComboGroup> all = ComboStore.all(plugin.configManager, plugin.gson);
			boolean changed = false;
			for (ComboGroup g : all)
			{
				if (cat.name.equals(g.category))
				{
					g.color = chosen.getRGB();
					changed = true;
				}
			}
			if (changed)
			{
				ComboStore.save(plugin.configManager, plugin.gson, all);
			}
			rebuild();
		});
		picker.setVisible(true);
	}

	private JPanel buildCreateForm()
	{
		JPanel form = new JPanel(new GridLayout(0, 1, 0, 4));
		form.setBorder(boxBorder());

		// Row 1: "Name" label + a name box that fills the rest of the row.
		form.add(labelled("Name", nameField));

		// File the new combo into an existing group from the start (remembers the selection across creates).
		List<String> options = new ArrayList<>();
		options.add("(none)");
		for (ComboCategory c : ComboStore.categories(plugin.configManager, plugin.gson))
		{
			options.add(c.name);
		}
		JComboBox<String> groupBox = new JComboBox<>(options.toArray(new String[0]));
		groupBox.setSelectedItem(options.contains(createCategory) ? createCategory : "(none)");
		groupBox.addActionListener(e -> {
			String sel = (String) groupBox.getSelectedItem();
			createCategory = "(none)".equals(sel) ? "" : sel;
		});
		createGroupBox = groupBox; // onCreate reads the live selection from here (not just the listener-set field)

		// Row 2: group dropdown | Create button (two equal halves).
		JButton create = new JButton("Create");
		create.addActionListener(e -> onCreate());
		JPanel actionRow = new JPanel(new GridLayout(1, 2, 6, 0));
		actionRow.add(groupBox);
		actionRow.add(create);
		form.add(actionRow);

		// Row 3: import a combo (or group) someone shared via clipboard.
		JButton importBtn = new JButton("Import from clipboard");
		importBtn.setToolTipText("Paste a copied combo or group — or several appended (e.g. a whole pastebin) to import them all at once");
		importBtn.addActionListener(e -> importFromClipboard());
		form.add(importBtn);
		return form;
	}

	private void onCreate()
	{
		String raw = nameField.getText().trim();
		if (raw.isEmpty())
		{
			return;
		}
		String name = ComboGroup.bracket(raw);
		if (group(name) != null)
		{
			nameField.setText(""); // clear the entry so the name isn't left behind on return
			openGroup(name); // already exists — just open it
			return;
		}
		// Read the dropdown's live selection (authoritative) rather than trusting the listener-set field,
		// which can be stale if the selection event hasn't been delivered before this click.
		if (createGroupBox != null)
		{
			String sel = (String) createGroupBox.getSelectedItem();
			createCategory = sel == null || "(none)".equals(sel) ? "" : sel;
		}
		ComboGroup g = new ComboGroup(name);
		if (!createCategory.isEmpty())
		{
			ComboCategory cat = ComboStore.category(plugin.configManager, plugin.gson, createCategory);
			if (cat != null)
			{
				g.category = cat.name;
				g.color = cat.color; // inherit the group's color on creation
				g.hideHighlight = cat.hideHighlight; // and its highlight on/off state
			}
		}
		save(g);
		nameField.setText("");
		openGroup(name);
		// Re-apply the group's color on the next EDT cycle. Creating, saving, and rebuilding the detail view
		// in one event can leave the new combo showing the default color; deferring re-reads the saved group
		// and its category and forces the inherited color through. No-op once the color already matches.
		SwingUtilities.invokeLater(() -> inheritCategoryColor(name));
	}

	/** Forces a group's color to match its category's color (no-op if ungrouped or already matching). */
	private void inheritCategoryColor(String groupName)
	{
		ComboGroup g = group(groupName);
		if (g == null || g.category == null || g.category.isEmpty())
		{
			return;
		}
		ComboCategory cat = ComboStore.category(plugin.configManager, plugin.gson, g.category);
		if (cat == null || g.color == cat.color)
		{
			return;
		}
		g.color = cat.color;
		save(g);
		if (groupName.equals(selectedGroup))
		{
			rebuild();
		}
	}

	// ---------------------------------------------------------------- clipboard import / export

	/** Copies a single combo's share string to the clipboard. */
	private void exportComboToClipboard(String name)
	{
		ComboGroup g = group(name);
		if (g == null)
		{
			return;
		}
		ComboCodec.toClipboard(ComboCodec.exportCombo(plugin.gson, g));
		toast("Copied combo \"" + stripBrackets(name) + "\" to the clipboard.");
	}

	/** Copies a category and all of its combos to the clipboard as one group share string. */
	private void exportGroupToClipboard(String categoryName)
	{
		ComboCategory cat = ComboStore.category(plugin.configManager, plugin.gson, categoryName);
		if (cat == null)
		{
			return;
		}
		ComboCodec.Bundle bundle = new ComboCodec.Bundle();
		bundle.category = cat;
		bundle.combos = new ArrayList<>();
		for (ComboGroup g : ComboStore.all(plugin.configManager, plugin.gson))
		{
			if (categoryName.equals(g.category))
			{
				bundle.combos.add(g);
			}
		}
		ComboCodec.toClipboard(ComboCodec.exportGroup(plugin.gson, bundle));
		toast("Copied group \"" + categoryName + "\" (" + bundle.combos.size() + " combos) to the clipboard.");
	}

	/** Reads the clipboard and imports every combo/group share token in it — one, or many appended at once. */
	private void importFromClipboard()
	{
		List<String> tokens = ComboCodec.extractTokens(ComboCodec.fromClipboard());
		if (tokens.isEmpty())
		{
			info("The clipboard doesn't contain a Combo Tags share string.");
			return;
		}
		if (tokens.size() == 1)
		{
			String t = tokens.get(0);
			if (ComboCodec.isGroupString(t))
			{
				importGroupString(t);
			}
			else
			{
				importComboString(t);
			}
			return;
		}
		importMany(tokens);
	}

	/**
	 * Imports several appended share tokens in one pass. Non-interactive (combos whose names already exist are
	 * skipped, no per-item prompts) with a single combos save and one summary — for a whole pastebin at once.
	 */
	private void importMany(List<String> tokens)
	{
		List<ComboGroup> all = ComboStore.all(plugin.configManager, plugin.gson);
		Set<String> taken = new HashSet<>();
		for (ComboGroup g : all)
		{
			taken.add(g.name);
		}
		int groups = 0, combos = 0, skipped = 0, failed = 0;
		for (String t : tokens)
		{
			if (ComboCodec.isGroupString(t))
			{
				ComboCodec.Bundle b = ComboCodec.importGroup(plugin.gson, t);
				if (b == null)
				{
					failed++;
					continue;
				}
				// Reuse a same-named category (merging into it); create it if new.
				if (ComboStore.category(plugin.configManager, plugin.gson, b.category.name) == null)
				{
					ComboStore.upsertCategory(plugin.configManager, plugin.gson, b.category);
				}
				for (ComboGroup g : b.combos)
				{
					if (g.name == null || g.name.isEmpty())
					{
						continue;
					}
					if (taken.contains(g.name))
					{
						skipped++; // a combo with this name already exists — leave it untouched
						continue;
					}
					g.category = b.category.name;
					taken.add(g.name);
					all.add(g);
					combos++;
				}
				groups++;
			}
			else
			{
				ComboGroup g = ComboCodec.importCombo(plugin.gson, t);
				if (g == null)
				{
					failed++;
					continue;
				}
				if (taken.contains(g.name))
				{
					skipped++; // already present — skip
					continue;
				}
				// An unknown category would hide the combo; drop it so it lands in Ungrouped.
				if (g.category != null && !g.category.isEmpty()
					&& ComboStore.category(plugin.configManager, plugin.gson, g.category) == null)
				{
					g.category = "";
				}
				taken.add(g.name);
				all.add(g);
				combos++;
			}
		}
		ComboStore.save(plugin.configManager, plugin.gson, all); // one write for every imported combo
		rebuild();
		info("Imported " + combos + (combos == 1 ? " combo" : " combos")
			+ (groups > 0 ? " across " + groups + (groups == 1 ? " group" : " groups") : "")
			+ (skipped > 0 ? ", " + skipped + " skipped (already present)" : "")
			+ (failed > 0 ? " (" + failed + " couldn't be read)" : "") + ".");
	}

	private void importComboString(String s)
	{
		ComboGroup g = ComboCodec.importCombo(plugin.gson, s);
		if (g == null)
		{
			info("That Combo Tags string couldn't be read (it may be corrupted).");
			return;
		}
		// A category that doesn't exist here would hide the combo (it's neither in a group nor ungrouped),
		// so drop an unknown category and let it land in Ungrouped.
		if (g.category != null && !g.category.isEmpty()
			&& ComboStore.category(plugin.configManager, plugin.gson, g.category) == null)
		{
			g.category = "";
		}
		if (group(g.name) != null)
		{
			info("A combo named \"" + stripBrackets(g.name) + "\" already exists — skipped.");
			return;
		}
		save(g);
		openGroup(g.name);
		info("Imported combo \"" + stripBrackets(g.name) + "\".");
	}

	private void importGroupString(String s)
	{
		ComboCodec.Bundle bundle = ComboCodec.importGroup(plugin.gson, s);
		if (bundle == null)
		{
			info("That Combo Tags group string couldn't be read (it may be corrupted).");
			return;
		}
		// Create the category if it's new (a same-named one is reused, merging the imported combos into it).
		if (ComboStore.category(plugin.configManager, plugin.gson, bundle.category.name) == null)
		{
			ComboStore.upsertCategory(plugin.configManager, plugin.gson, bundle.category);
		}
		int imported = 0, skipped = 0;
		for (ComboGroup g : bundle.combos)
		{
			if (g.name == null || g.name.isEmpty())
			{
				continue;
			}
			if (group(g.name) != null)
			{
				skipped++; // a combo with this name already exists — leave it untouched
				continue;
			}
			g.category = bundle.category.name;
			save(g);
			imported++;
		}
		rebuild();
		info("Imported group \"" + bundle.category.name + "\" (" + imported + " combos"
			+ (skipped > 0 ? ", " + skipped + " skipped" : "") + ").");
	}

	private void info(String message)
	{
		JOptionPane.showMessageDialog(this, message, "Combo Tags", JOptionPane.INFORMATION_MESSAGE);
	}

	/**
	 * A brief, non-blocking tooltip-style "toast" near the cursor that fades out on its own — used for
	 * copy-to-clipboard confirmations so they don't interrupt with a modal dialog. Falls back to a timed show
	 * (no fade) where window translucency isn't supported.
	 */
	private void toast(String message)
	{
		Window owner = SwingUtilities.getWindowAncestor(this);
		JWindow toast = new JWindow(owner);
		toast.setFocusableWindowState(false); // never steal focus

		JLabel label = new JLabel(message);
		label.setOpaque(true);
		label.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		label.setForeground(Color.WHITE);
		label.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR), new EmptyBorder(6, 10, 6, 10)));
		toast.add(label);
		toast.pack();

		// Appear just below-right of the pointer, clamped to the screen.
		Point at;
		try
		{
			at = MouseInfo.getPointerInfo().getLocation();
			at.translate(12, 12);
		}
		catch (Exception ex)
		{
			at = new Point(0, 0);
		}
		Rectangle screen = GraphicsEnvironment.getLocalGraphicsEnvironment()
			.getDefaultScreenDevice().getDefaultConfiguration().getBounds();
		int x = Math.min(Math.max(screen.x, at.x), screen.x + screen.width - toast.getWidth());
		int y = Math.min(Math.max(screen.y, at.y), screen.y + screen.height - toast.getHeight());
		toast.setLocation(x, y);

		boolean canFade = GraphicsEnvironment.getLocalGraphicsEnvironment().getDefaultScreenDevice()
			.isWindowTranslucencySupported(GraphicsDevice.WindowTranslucency.TRANSLUCENT);
		toast.setVisible(true);

		// Hold briefly, then fade out (or just dispose if translucency is unsupported).
		Timer hold = new Timer(900, null);
		hold.setRepeats(false);
		hold.addActionListener(e ->
		{
			if (!canFade)
			{
				toast.dispose();
				return;
			}
			final float[] opacity = {1f};
			Timer fade = new Timer(45, null);
			fade.addActionListener(fe ->
			{
				opacity[0] -= 0.12f;
				if (opacity[0] <= 0f)
				{
					fade.stop();
					toast.dispose();
					return;
				}
				try
				{
					toast.setOpacity(opacity[0]);
				}
				catch (Exception ex)
				{
					fade.stop();
					toast.dispose();
				}
			});
			fade.start();
		});
		hold.start();
	}

	private JPanel buildGroupRow(String name, boolean indented)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBorder(indented
			? BorderFactory.createCompoundBorder(new EmptyBorder(0, 12, 0, 0), rowBorder())
			: rowBorder());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

		ComboGroup g = group(name);
		int count = g != null ? g.members.size() : 0;

		// The combo's icon (its favorite, or the top member by default), flush to the left.
		if (g != null && !g.members.isEmpty())
		{
			row.add(iconLabel(g.displayIconId()), BorderLayout.WEST);
		}

		// Center: plain name (no brackets — they waste horizontal space) plus the item count.
		JButton open = new JButton("<html><b>" + htmlEscape(stripBrackets(name)) + "</b><br>"
			+ count + (count == 1 ? " item" : " items") + "</html>");
		open.setHorizontalAlignment(SwingConstants.LEFT);
		open.setToolTipText("Manage items in this group");
		open.addActionListener(e -> openGroup(name));
		row.add(open, BorderLayout.CENTER);

		// Right-click to reorder within this section (order is the stored combos order) or delete (confirmed).
		JPopupMenu menu = new JPopupMenu();
		JMenuItem up = new JMenuItem("Move up");
		up.addActionListener(e -> {
			ComboStore.moveCombo(plugin.configManager, plugin.gson, name, -1);
			rebuild();
		});
		JMenuItem down = new JMenuItem("Move down");
		down.addActionListener(e -> {
			ComboStore.moveCombo(plugin.configManager, plugin.gson, name, +1);
			rebuild();
		});
		JMenuItem replaceInTab = new JMenuItem("Replace in tab");
		replaceInTab.setToolTipText("Removes this combo's member items from the open tag tab and puts the cell where they were");
		replaceInTab.addActionListener(e -> plugin.replaceComboInOpenTab(name));
		JMenuItem replaceAllTabs = new JMenuItem("Replace in all tabs");
		replaceAllTabs.setToolTipText("Consolidate this combo's loose items into a cell in every layout-enabled tab that has them");
		replaceAllTabs.addActionListener(e -> plugin.replaceComboInAllTabs(name));
		JMenuItem copy = new JMenuItem("Copy to clipboard");
		copy.addActionListener(e -> exportComboToClipboard(name));
		JMenuItem delete = new JMenuItem("Delete");
		delete.addActionListener(e -> {
			if (confirmDelete("combo \"" + stripBrackets(name) + "\""))
			{
				// Plugin removes the combo, replaces its cells with the goal placeholder, then rebuilds this panel.
				plugin.deleteCombo(name);
			}
		});
		menu.add(replaceInTab);
		menu.add(replaceAllTabs);
		menu.addSeparator();
		menu.add(up);
		menu.add(down);
		menu.addSeparator();
		menu.add(copy);
		menu.addSeparator();
		menu.add(delete);
		row.setComponentPopupMenu(menu);
		open.setComponentPopupMenu(menu);
		return row;
	}

	/** Opens a combo's editor in the panel (e.g. from the bank ghost's "Open Combo Tag"). EDT only. */
	public void openCombo(String name)
	{
		if (group(name) != null)
		{
			openGroup(name);
		}
	}

	private void openGroup(String name)
	{
		selectedGroup = name;
		searchQuery = "";
		searchField.setText(""); // keep the visible field in sync with the reset search state
		searchResults = new ArrayList<>();
		expandedBase = null;
		searchSlotFilter = detectSlotFilter(group(name)); // default the search to this combo's slot
		rebuild();
		if (!ItemIndex.isReady())
		{
			// Slot detection needs the item index; if it isn't built yet, build it off-thread then refine the
			// default (and re-render) — but only if we're still on this same combo.
			plugin.clientThread.invokeLater(() -> {
				ItemIndex.build(plugin.client, plugin.itemManager);
				SwingUtilities.invokeLater(() -> {
					if (name.equals(selectedGroup))
					{
						searchSlotFilter = detectSlotFilter(group(name));
						rebuild();
					}
				});
			});
		}
	}

	/**
	 * The slot the "Add items" search should default to for a combo: the shared equipment slot of its members
	 * (so a head-slot combo opens filtered to Head). Falls back to {@link ItemIndex#SLOT_EQUIPPABLE} for an
	 * empty combo, a mixed-slot combo, or before the index is built. Member-slot lookups are O(1).
	 */
	private int detectSlotFilter(ComboGroup g)
	{
		if (g == null || g.members.isEmpty() || !ItemIndex.isReady())
		{
			return ItemIndex.SLOT_EQUIPPABLE;
		}
		int slot = ItemIndex.NOT_EQUIPPABLE;
		for (int base : g.members)
		{
			int s = ItemIndex.slotOf(ItemIndex.canonicalBase(base));
			if (s == ItemIndex.NOT_EQUIPPABLE)
			{
				continue; // unknown/non-equippable member doesn't constrain the slot
			}
			if (slot == ItemIndex.NOT_EQUIPPABLE)
			{
				slot = s;
			}
			else if (slot != s)
			{
				return ItemIndex.SLOT_EQUIPPABLE; // members span multiple slots → don't narrow
			}
		}
		return slot == ItemIndex.NOT_EQUIPPABLE ? ItemIndex.SLOT_EQUIPPABLE : slot;
	}

	// -------------------------------------------------------------- detail view

	private void buildDetailView(JPanel content, ComboGroup g)
	{
		if (g == null)
		{
			// Group was deleted out from under us; fall back to the list.
			selectedGroup = null;
			buildListView(content);
			return;
		}
		String name = g.name;

		JButton back = new JButton("← Back");
		back.addActionListener(e -> {
			selectedGroup = null;
			rebuild();
		});
		content.add(back); // delete is via right-click (with confirmation) on the combo's row in the list
		content.add(Box.createVerticalStrut(8));

		content.add(title(stripBrackets(name)));
		content.add(Box.createVerticalStrut(4));

		// Group selector (a dropdown button) and the color picker share one line, 50/50, so they line up with
		// the Add/Replace buttons below.
		JComboBox<String> groupSelector = buildCategorySelector(g);
		JButton colorSwatch = buildColorSwatch(new Color(g.color), c -> {
			ComboGroup cur = group(name);
			if (cur != null)
			{
				cur.color = c.getRGB();
				save(cur);
			}
		});
		JPanel groupColorRow = new JPanel(new GridLayout(1, 2, 4, 0));
		groupColorRow.setOpaque(false);
		groupColorRow.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			Math.max(groupSelector.getPreferredSize().height, colorSwatch.getPreferredSize().height)));
		groupColorRow.add(groupSelector);
		groupColorRow.add(colorSwatch);
		content.add(groupColorRow);
		content.add(Box.createVerticalStrut(4));
		content.add(buildHighlightToggle(g));
		content.add(Box.createVerticalStrut(6));

		// Add / Replace share one line (short labels so they fit side by side).
		JButton addToTab = new JButton("Add to Tab");
		addToTab.setToolTipText("<html>Embeds this combo as a smart cell in the bank tag tab you currently have open."
			+ "<br>If the combo's member items are already loose in the tab, they're consolidated into the cell.</html>");
		addToTab.addActionListener(e -> plugin.addComboToOpenTab(name));

		JButton replaceInTab = new JButton("Replace in Tab");
		replaceInTab.setToolTipText("<html>Removes this combo's member items from the open tag tab and"
			+ "<br>puts the combo cell where the top-left-most one was.</html>");
		replaceInTab.addActionListener(e -> plugin.replaceComboInOpenTab(name));

		JPanel tabActions = new JPanel(new GridLayout(1, 2, 4, 0));
		tabActions.setOpaque(false);
		tabActions.setMaximumSize(new Dimension(Integer.MAX_VALUE, addToTab.getPreferredSize().height));
		tabActions.add(addToTab);
		tabActions.add(replaceInTab);
		content.add(tabActions);
		content.add(Box.createVerticalStrut(10));

		content.add(sectionLabel("Members"));
		if (g.members.isEmpty())
		{
			content.add(hint("No items yet — search below to add."));
		}
		else
		{
			for (int i = 0; i < g.members.size(); i++)
			{
				int baseId = g.members.get(i);
				content.add(buildMemberRow(g, baseId));
				content.add(Box.createVerticalStrut(4));

				if (expandedBase != null && expandedBase == baseId)
				{
					int selected = selectedVariant(g, baseId);
					for (Integer variantId : orderedVariants(g, baseId))
					{
						content.add(buildVariantRow(name, baseId, variantId, variantId == selected));
						content.add(Box.createVerticalStrut(2));
					}
				}
			}
		}

		content.add(Box.createVerticalStrut(6));
		content.add(sectionLabel("Add items"));
		content.add(labelled("Slot", buildSlotFilter()));
		content.add(Box.createVerticalStrut(4));
		content.add(buildSearchBar());
		if (indexBuilding)
		{
			content.add(Box.createVerticalStrut(4));
			content.add(hint("Building item index (one-time)…"));
		}
		for (ItemIndex.Entry result : searchResults)
		{
			content.add(Box.createVerticalStrut(4));
			content.add(buildResultRow(name, result));
		}
	}

	/** Checkbox: when unticked, this combo's cell draws no bank overlay highlight (the item still renders). */
	private JCheckBox buildHighlightToggle(ComboGroup g)
	{
		JCheckBox box = new JCheckBox("Highlight in bank", !g.hideHighlight);
		box.setOpaque(false);
		box.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		box.setToolTipText("<html>Draw this combo's overlay box/dot/etc. on its bank cell.<br>"
			+ "Unticked: the cell still shows its item, but with no highlight even when the bank overlay is on.</html>");
		box.addActionListener(e -> {
			ComboGroup cur = group(g.name);
			if (cur != null)
			{
				cur.hideHighlight = !box.isSelected();
				save(cur); // ConfigChanged invalidates the overlay's hide cache and relayouts the bank
			}
		});
		return box;
	}

	/** Dropdown to file this combo under a category (or none). */
	private JComboBox<String> buildCategorySelector(ComboGroup g)
	{
		List<String> options = new ArrayList<>();
		options.add("(none)");
		for (ComboCategory c : ComboStore.categories(plugin.configManager, plugin.gson))
		{
			options.add(c.name);
		}
		JComboBox<String> box = new JComboBox<>(options.toArray(new String[0]));
		box.setSelectedItem(g.category == null || g.category.isEmpty() ? "(none)" : g.category);
		box.addActionListener(e -> {
			String sel = (String) box.getSelectedItem();
			ComboGroup cur = group(g.name);
			if (cur != null)
			{
				cur.category = "(none)".equals(sel) ? "" : sel;
				// Filing a combo into a group adopts that group's color (same semantics as creation and
				// the group color picker, which force-recolor every member). "(none)" leaves color as-is.
				if (!cur.category.isEmpty())
				{
					ComboCategory cat = ComboStore.category(plugin.configManager, plugin.gson, cur.category);
					if (cat != null)
					{
						cur.color = cat.color;
						cur.hideHighlight = cat.hideHighlight;
					}
				}
				save(cur);
				rebuild(); // refresh the detail view's color swatch to the inherited color
			}
		});
		return box;
	}

	/** Dropdown that restricts the item search to an equipment slot (or any equippable / any item). */
	private JComboBox<String> buildSlotFilter()
	{
		JComboBox<String> box = new JComboBox<>(SLOT_FILTER_LABELS);
		box.setToolTipText("Restrict the item search to an equipment slot");
		for (int i = 0; i < SLOT_FILTER_VALUES.length; i++)
		{
			if (SLOT_FILTER_VALUES[i] == searchSlotFilter)
			{
				box.setSelectedIndex(i); // set before wiring the listener so it doesn't fire on build
				break;
			}
		}
		box.addActionListener(e -> {
			int idx = box.getSelectedIndex();
			if (idx >= 0)
			{
				searchSlotFilter = SLOT_FILTER_VALUES[idx];
				doSearch(); // re-run the current query under the new slot
			}
		});
		return box;
	}

	private JPanel buildSearchBar()
	{
		// Re-parent the persistent field (adding it to a new container removes it from the old one), so its
		// typed text and caret survive this rebuild even when the rebuild was triggered by a non-search action.
		// Listeners are attached once at construction — do NOT re-add them here.
		JPanel bar = new JPanel(new BorderLayout(4, 0));
		JButton search = new JButton("Search");
		search.addActionListener(e -> doSearch());

		bar.add(searchField, BorderLayout.CENTER);
		bar.add(search, BorderLayout.EAST);
		return bar;
	}

	/** Runs the item search from the live persistent-field text. Wired to Enter (once) and the Search button. */
	private void doSearch()
	{
		searchQuery = searchField.getText().trim();
		if (searchQuery.isEmpty())
		{
			searchResults = new ArrayList<>();
			rebuild();
			return;
		}
		if (ItemIndex.isReady())
		{
			searchResults = ItemIndex.search(searchQuery, MAX_SEARCH_RESULTS, searchSlotFilter);
			rebuild();
		}
		else
		{
			// First search builds the full item index on the client thread (getItemComposition).
			indexBuilding = true;
			searchResults = new ArrayList<>();
			rebuild();
			int slotFilter = searchSlotFilter;
			plugin.clientThread.invokeLater(() -> {
				ItemIndex.build(plugin.client, plugin.itemManager);
				List<ItemIndex.Entry> results = ItemIndex.search(searchQuery, MAX_SEARCH_RESULTS, slotFilter);
				SwingUtilities.invokeLater(() -> {
					indexBuilding = false;
					searchResults = results;
					rebuild();
				});
			});
		}
	}

	private JPanel buildMemberRow(ComboGroup g, int baseId)
	{
		int displayId = selectedVariant(g, baseId);
		int variantCount = variantOptions(baseId).size();

		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBorder(rowBorder());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));
		row.setToolTipText("Drag to reorder (higher in the list = higher priority)");
		row.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
		row.putClientProperty(MEMBER_BASE_ID, baseId);
		row.putClientProperty(DEFAULT_BORDER, rowBorder());
		attachReorderDrag(row, this::isMemberRow, gap -> applyReorder(g.name, baseId, gap));

		row.add(iconLabel(displayId), BorderLayout.WEST);
		row.add(nameLabel(displayId), BorderLayout.CENTER);

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		// One control per row: a member WITH variants shows only the dropdown (the favorite is chosen per-variant
		// in the expanded rows); a singular member shows only its favorite star. Either way it sits flush-right.
		if (variantCount > 1)
		{
			boolean expanded = expandedBase != null && expandedBase == baseId;
			JButton toggle = new JButton(expanded ? "▾" : "▸");
			toggle.setToolTipText("Show " + variantCount + " variants");
			toggle.addActionListener(e -> {
				expandedBase = expanded ? null : baseId;
				rebuild();
			});
			buttons.add(toggle);
		}
		else
		{
			boolean memberIsFavorite = g.favoriteOwner() == baseId;
			JButton fav = new JButton(memberIsFavorite ? "★" : "☆");
			fav.setToolTipText(memberIsFavorite ? "This is the combo icon (click to unset)" : "Use as the combo icon");
			fav.addActionListener(e -> toggleFavorite(g.name, displayId));
			buttons.add(fav);
		}

		row.add(buttons, BorderLayout.EAST);

		// Remove is now a right-click action on the row (the old inline ✕ button is gone). The row's drag
		// handler only arms on the left button, so right-click is free for the popup.
		JPopupMenu menu = new JPopupMenu();
		JMenuItem remove = new JMenuItem("Remove from group");
		remove.addActionListener(e -> {
			ComboGroup cur = group(g.name);
			if (cur != null)
			{
				cur.members.remove((Integer) baseId);
				cur.variantOrder.remove(baseId);
				if (cur.icon != 0 && cur.favoriteOwner() == -1)
				{
					cur.icon = 0; // favorite's member is gone → back to the default icon
				}
				save(cur);
				rebuild();
			}
		});
		menu.add(remove);
		row.setComponentPopupMenu(menu);
		return row;
	}

	/** An indented row under an expanded member: one variant, draggable to set its resolution priority. */
	private JPanel buildVariantRow(String name, int baseId, int variantId, boolean selected)
	{
		javax.swing.border.Border border = BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR), new EmptyBorder(3, 20, 3, 6));

		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBorder(border);
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		row.setToolTipText("Drag to reorder (higher = preferred when you own several of this item)");
		row.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
		row.putClientProperty(VARIANT_OWNER, baseId);
		row.putClientProperty(DEFAULT_BORDER, border);
		attachReorderDrag(row, c -> isVariantRowOf(c, baseId), gap -> applyVariantReorder(name, baseId, variantId, gap));

		row.add(iconLabel(variantId), BorderLayout.WEST);

		JLabel nameLbl = nameLabel(variantId);
		if (selected)
		{
			nameLbl.setForeground(ColorScheme.BRAND_ORANGE);
		}
		row.add(nameLbl, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Favorite only (the old "use" button is gone — the served version is whichever variant is dragged to the
		// top of the order). Flush-right so it lines up with the member row's favorite.
		ComboGroup gFav = group(name);
		boolean isFavorite = gFav != null && gFav.icon == variantId;
		JButton fav = new JButton(isFavorite ? "★" : "☆");
		fav.setToolTipText(isFavorite ? "This is the combo icon (click to unset)" : "Use this version as the combo icon");
		fav.addActionListener(e -> toggleFavorite(name, variantId));
		buttons.add(fav);

		row.add(buttons, BorderLayout.EAST);
		return row;
	}

	private JPanel buildResultRow(String name, ItemIndex.Entry result)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBorder(rowBorder());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));

		row.add(iconLabel(result.displayId), BorderLayout.WEST);
		row.add(new JLabel(result.name), BorderLayout.CENTER);

		JButton add = new JButton("+");
		add.setToolTipText("Add to group");
		add.addActionListener(e -> {
			ComboGroup cur = group(name);
			if (cur == null)
			{
				return;
			}
			// A recolor collapses onto its canonical base (so all variants are one member). Adding a specific
			// version serves it by putting it on top of that member's variant order; adding the bare base clears
			// any ordering so the default (functional item) is served.
			int canonical = ItemIndex.canonicalBase(result.id);
			if (!cur.members.contains(canonical))
			{
				cur.members.add(canonical);
			}
			if (result.id == canonical)
			{
				cur.variantOrder.remove(canonical);
			}
			else
			{
				List<Integer> order = new ArrayList<>(orderedVariants(cur, canonical));
				order.remove((Integer) result.id);
				order.add(0, result.id);
				cur.variantOrder.put(canonical, order);
			}
			save(cur);
			rebuild();
		});
		row.add(add, BorderLayout.EAST);
		return row;
	}

	// Client-property keys: mark a member row (value = base id), mark a variant row (value = owner base id),
	// and cache each row's normal border so the drag insertion indicator can restore it.
	private static final String MEMBER_BASE_ID = "comboMemberBaseId";
	private static final String VARIANT_OWNER = "comboVariantOwner";
	private static final String DEFAULT_BORDER = "comboDefaultBorder";

	private boolean isMemberRow(Component c)
	{
		return c instanceof JComponent && ((JComponent) c).getClientProperty(MEMBER_BASE_ID) != null;
	}

	private boolean isVariantRowOf(Component c, int owner)
	{
		return c instanceof JComponent
			&& Objects.equals(((JComponent) c).getClientProperty(VARIANT_OWNER), owner);
	}

	/**
	 * Makes a row draggable to reorder it among its siblings (rows matching {@code isSibling}); the new order is
	 * committed via {@code onDrop} on release. While dragging, an orange line marks where the row will land. Drives
	 * both member reorder (priority) and variant reorder. Replaces the old ▲▼ priority buttons.
	 */
	private void attachReorderDrag(JPanel row, Predicate<Component> isSibling, IntConsumer onDrop)
	{
		MouseAdapter ma = new MouseAdapter()
		{
			private boolean armed = false;
			private boolean moved = false;

			@Override
			public void mousePressed(MouseEvent e)
			{
				armed = SwingUtilities.isLeftMouseButton(e);
				moved = false;
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				if (!armed)
				{
					return;
				}
				moved = true;
				row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
				showInsertionIndicator(row, isSibling, targetGap(row, isSibling, e));
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (!armed)
				{
					return;
				}
				armed = false;
				if (!moved)
				{
					return; // a plain click on the row body, not a drag
				}
				onDrop.accept(targetGap(row, isSibling, e)); // onDrop's rebuild() clears all drag visuals
			}
		};
		row.addMouseListener(ma);
		row.addMouseMotionListener(ma);
	}

	/** The insertion index (0..n) among the OTHER sibling rows for the cursor's current vertical position. */
	private int targetGap(JComponent draggedRow, Predicate<Component> isSibling, MouseEvent e)
	{
		Container parent = draggedRow.getParent();
		if (parent == null)
		{
			return 0;
		}
		Point p = SwingUtilities.convertPoint(draggedRow, e.getPoint(), parent);
		int gap = 0;
		for (Component c : parent.getComponents())
		{
			if (c == draggedRow || !isSibling.test(c))
			{
				continue;
			}
			if (p.y > c.getY() + c.getHeight() / 2)
			{
				gap++;
			}
		}
		return gap;
	}

	/** Draws an orange line at the drop position: top of the gap row, or bottom of the last row for end-insert. */
	private void showInsertionIndicator(JComponent draggedRow, Predicate<Component> isSibling, int gap)
	{
		Container parent = draggedRow.getParent();
		if (parent == null)
		{
			return;
		}
		List<JComponent> rows = new ArrayList<>();
		for (Component c : parent.getComponents())
		{
			if (c != draggedRow && isSibling.test(c))
			{
				rows.add((JComponent) c);
			}
		}
		for (JComponent r : rows)
		{
			r.setBorder(defaultBorder(r)); // reset the indicator from the previous drag position
		}
		if (rows.isEmpty())
		{
			return;
		}
		JComponent target = rows.get(Math.min(gap, rows.size() - 1));
		int top = gap < rows.size() ? 2 : 0;
		int bottom = gap < rows.size() ? 0 : 2;
		target.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(top, 0, bottom, 0, ColorScheme.BRAND_ORANGE), defaultBorder(target)));
		parent.repaint();
	}

	/** A row's normal (non-indicator) border, cached as a client property when the row is built. */
	private javax.swing.border.Border defaultBorder(JComponent row)
	{
		Object b = row.getClientProperty(DEFAULT_BORDER);
		return b instanceof javax.swing.border.Border ? (javax.swing.border.Border) b : rowBorder();
	}

	/** Moves the dragged member to the drop gap, persists the new priority order, and re-renders. */
	private void applyReorder(String name, int baseId, int gap)
	{
		ComboGroup cur = group(name);
		if (cur == null)
		{
			rebuild();
			return;
		}
		int from = cur.members.indexOf(baseId);
		if (from < 0)
		{
			rebuild();
			return;
		}
		Integer member = cur.members.remove(from);
		int to = Math.max(0, Math.min(gap, cur.members.size()));
		cur.members.add(to, member);
		if (to != from)
		{
			save(cur);
		}
		rebuild();
	}

	/** A member's variants in display order: the stored priority order (valid options first), else the default. */
	private List<Integer> orderedVariants(ComboGroup g, int baseId)
	{
		List<Integer> all = variantOptions(baseId);
		List<Integer> stored = g.variantOrder == null ? null : g.variantOrder.get(baseId);
		if (stored == null || stored.isEmpty())
		{
			return all;
		}
		List<Integer> result = new ArrayList<>(all.size());
		for (Integer v : stored)
		{
			if (all.contains(v))
			{
				result.add(v); // stored order, dropping any variants the game no longer reports
			}
		}
		for (Integer v : all)
		{
			if (!result.contains(v))
			{
				result.add(v); // append any newly-available variants not yet in the stored order
			}
		}
		return result;
	}

	/** Moves the dragged variant to the drop gap and persists this member's variant priority order. */
	private void applyVariantReorder(String name, int baseId, int variantId, int gap)
	{
		ComboGroup cur = group(name);
		if (cur == null)
		{
			rebuild();
			return;
		}
		List<Integer> order = new ArrayList<>(orderedVariants(cur, baseId));
		int from = order.indexOf(variantId);
		if (from < 0)
		{
			rebuild();
			return;
		}
		Integer v = order.remove(from);
		int to = Math.max(0, Math.min(gap, order.size()));
		order.add(to, v);
		cur.variantOrder.put(baseId, order);
		if (to != from)
		{
			save(cur);
		}
		rebuild();
	}

	/** The variant currently served (shown/highlighted) for a member: the top of its priority order. */
	private int selectedVariant(ComboGroup g, int baseId)
	{
		return g.servedVariant(baseId);
	}

	/** Modal yes/no confirmation before a destructive delete; returns true only if the user confirmed. */
	private boolean confirmDelete(String what)
	{
		int choice = JOptionPane.showConfirmDialog(this, "Delete " + what + "?", "Confirm delete",
			JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		return choice == JOptionPane.YES_OPTION;
	}

	/** Group-delete prompt: keep the combos (un-file them), delete the combos too, or cancel. */
	private void promptDeleteGroup(ComboCategory cat)
	{
		Object[] options = {"Group", "Group with contents", "Cancel"};
		int choice = JOptionPane.showOptionDialog(this,
			"Delete group \"" + cat.name + "\"?\n\n"
				+ "Group: removes the group; its combos become ungrouped.\n"
				+ "Group with contents: also deletes every combo in the group.",
			"Delete group", JOptionPane.YES_NO_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE,
			null, options, options[2]); // default to Cancel
		if (choice == 0) // Group
		{
			ComboStore.deleteCategory(plugin.configManager, plugin.gson, cat.name);
			rebuild();
		}
		else if (choice == 1) // Group with contents
		{
			// Plugin deletes the combos, replaces each cell with its goal placeholder, then rebuilds this panel.
			plugin.deleteCategoryWithContents(cat.name);
		}
	}

	/** Sets (or, if already favorited, clears) the combo's favorite display icon to a specific item id. */
	private void toggleFavorite(String name, int itemId)
	{
		ComboGroup cur = group(name);
		if (cur == null)
		{
			return;
		}
		cur.icon = cur.icon == itemId ? 0 : itemId;
		save(cur);
		rebuild();
	}

	/**
	 * Selectable display variants for a member: RuneLite's native variation group PLUS the stat-duplicate
	 * recolors the search folded into this base (e.g. Sanguine Torva under Torva full helm), restricted to
	 * equippable versions (so a DT2 ring's non-equippable old base model is hidden). The folded ids only appear
	 * once the item index has been built (i.e. after a search).
	 */
	private List<Integer> variantOptions(int baseId)
	{
		return ItemIndex.variants(baseId);
	}

	// --------------------------------------------------------------- icon/name + small widgets

	/** Item icon label (icon loads async; safe from the EDT). */
	private JLabel iconLabel(int itemId)
	{
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		plugin.itemManager.getImage(itemId).addTo(icon);
		return icon;
	}

	/** Item name label; resolved on the client thread (getItemComposition asserts it under -ea), then set on the EDT. */
	private JLabel nameLabel(int itemId)
	{
		JLabel label = new JLabel("…");
		plugin.clientThread.invokeLater(() -> {
			String resolved = plugin.itemManager.getItemComposition(itemId).getName();
			SwingUtilities.invokeLater(() -> label.setText(resolved));
		});
		return label;
	}

	private static String htmlEscape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Display form of a combo name with the surrounding [ ] stripped (the brackets are storage-only). */
	private static String stripBrackets(String name)
	{
		return (name.length() >= 2 && name.startsWith("[") && name.endsWith("]"))
			? name.substring(1, name.length() - 1) : name;
	}

	private JLabel title(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		return label;
	}

	private JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(new EmptyBorder(6, 0, 2, 0));
		return label;
	}

	private JLabel hint(String text)
	{
		JLabel label = new JLabel(text);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(new EmptyBorder(8, 0, 0, 0));
		return label;
	}

	/** A color "Pick" button tinted with the current color; opens the picker (anchored to the button) on click. */
	private JButton buildColorSwatch(Color current, Consumer<Color> onPick)
	{
		JButton swatch = new JButton("Pick");
		swatch.setBackground(current);
		swatch.setOpaque(true);
		swatch.setToolTipText("Choose the color for this combo");
		swatch.addActionListener(e -> {
			net.runelite.client.ui.components.colorpicker.RuneliteColorPicker picker =
				plugin.colorPickerManager.create(
					javax.swing.SwingUtilities.getWindowAncestor(this), current, "Combo color", false);
			placePickerNear(picker, swatch);
			picker.setOnClose(chosen -> {
				onPick.accept(chosen);
				rebuild();
			});
			picker.setVisible(true);
		});
		return swatch;
	}

	/**
	 * Anchors the color picker's TOP-RIGHT corner to the clicked button (the color buttons sit on the panel's
	 * right edge), so it opens beside the button instead of off the client's top-left. Clamped to the screen.
	 */
	private void placePickerNear(net.runelite.client.ui.components.colorpicker.RuneliteColorPicker picker, Component anchor)
	{
		try
		{
			java.awt.Point loc = anchor.getLocationOnScreen();
			Dimension size = picker.getSize();
			int x = Math.max(0, loc.x + anchor.getWidth() - size.width);
			int y = Math.max(0, loc.y);
			picker.setLocation(x, y);
		}
		catch (java.awt.IllegalComponentStateException ignored)
		{
			// anchor not currently on screen — leave the picker's default location
		}
	}

	private JPanel labelled(String text, Component field)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		JLabel label = new JLabel(text);
		label.setPreferredSize(new Dimension(60, label.getPreferredSize().height));
		row.add(label, BorderLayout.WEST);
		row.add(field, BorderLayout.CENTER);
		return row;
	}

	private javax.swing.border.Border boxBorder()
	{
		return BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.DARK_GRAY_COLOR), new EmptyBorder(8, 8, 8, 8));
	}

	private javax.swing.border.Border rowBorder()
	{
		return BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR), new EmptyBorder(4, 6, 4, 6));
	}
}

package com.combotags;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

/**
 * Resolves a combo group's "winner": from the group's ordered member list ({@link ComboGroup#members},
 * highest priority first), the highest-priority item the player currently has in the bank. If none are
 * in the bank, the top-priority member is returned as a "goal" (renders as a ghost), using the panel's
 * chosen display variant.
 */
@Slf4j
@RequiredArgsConstructor
public class ComboResolver
{
	private final ComboTagsPlugin plugin;

	// A base id -> actual bank item id snapshot, rebuilt lazily and reused until the bank changes. resolveWinner
	// runs per cell across every host tab on each bank refresh (plus reconcile/sync/render the same tick), so
	// without this each call would rescan the whole bank container. Invalidated from onItemContainerChanged(BANK).
	// Client-thread only (every reader canonicalizes, which asserts the client thread).
	private Map<Integer, Integer> bankByBaseCache;
	// canonicalize(id) -> actual bank item id, VARIANT-level (distinguishes recolors / charge states that share a
	// base). Drives per-member variant priority. Built and invalidated alongside bankByBaseCache.
	private Map<Integer, Integer> bankByVariantCache;
	// As above, but ALSO counting leftover bank placeholders (mapped to the real item they stand for). Used only by
	// resolveRestoreItem: when a combo cell is deleted, a placeholder still means "you have this", so it's restored.
	private Map<Integer, Integer> bankByBasePresentCache;
	private Map<Integer, Integer> bankByVariantPresentCache;

	// comboName -> canonical bases of that combo that ALSO appear in another combo of the SAME non-empty category.
	// Such a base is "contested": no single cell can own it without two cells fighting over the one physical item,
	// so it is excluded from winner resolution AND membership/scrub — the item is left unmanaged by the combos.
	// Cached against the combos-JSON string (any save writes a new string → the key mismatches and we recompute).
	private volatile String sharedCacheJson;
	private volatile Map<String, Set<Integer>> sharedBasesByCombo;

	/** Drops the cached bank snapshots. Call when the BANK container changes so the next resolve rescans. */
	public void invalidateBankCache()
	{
		bankByBaseCache = null;
		bankByVariantCache = null;
		bankByBasePresentCache = null;
		bankByVariantPresentCache = null;
	}

	/**
	 * The item id a combo "smart cell" should display: the highest-priority member present IN THE BANK
	 * (returned as the real bank item id so it renders solid), else the top-priority member as a ghost
	 * goal. Returns {@code -1} if the group is unknown or has no members.
	 */
	public int resolveWinner(String name)
	{
		// READ-ONLY: only reads members / variantOrder / displayIconId, so the shared cached snapshot is safe.
		ComboGroup group = ComboStore.cachedGet(plugin.configManager, plugin.gson, name);
		if (group == null || group.members.isEmpty())
		{
			return -1;
		}

		Map<Integer, Integer> bankByBase = bankItemsByBase();
		Map<Integer, Integer> bankByVariant = bankItemsByVariant();
		Set<Integer> shared = sharedBases(name);
		for (Integer base : group.members)
		{
			// A base shared with another combo in this category is never assigned to a cell (see sharedBases).
			if (shared.contains(ItemIndex.canonicalBase(base)))
			{
				continue;
			}
			// If the user gave this member a variant priority order, the highest-priority OWNED variant wins
			// (variant-level match, so a specific recolor/version is preferred when several are held).
			List<Integer> order = group.variantOrder == null ? null : group.variantOrder.get(base);
			if (order != null)
			{
				for (Integer variant : order)
				{
					Integer actual = bankByVariant.get(plugin.itemManager.canonicalize(variant));
					if (actual != null)
					{
						return actual;
					}
				}
			}
			// Default / fallback: any owned variant of this member counts. Canonicalize the member too, so a
			// member stored as a stat-duplicate still matches the bank (which is keyed by the canonical base).
			Integer actual = bankByBase.get(ItemIndex.canonicalBase(base));
			if (actual != null)
			{
				return actual;
			}
		}
		// None in the bank → ghost: the combo's favorite icon (or the top member's chosen variant).
		// Guard against a corrupt/imported variantOrder mapping a base to 0/negative: displayIconId() can
		// then be non-positive, which callers' (winner > 0) checks would mishandle (a negative id could be
		// pinned). Collapse any non-positive result to the documented -1 "unknown/no members" sentinel.
		int ghost = group.displayIconId();
		return ghost > 0 ? ghost : -1;
	}

	/**
	 * The item to leave behind when a combo's cell is removed (on delete): the highest-priority member you have
	 * in the bank as a real item OR a leftover bank placeholder (returned as the real item id, so it relays as the
	 * item or its placeholder). Only if NONE of the combo's items are in the bank at all does it fall back to the
	 * combo's goal — its favorite, else its top member. Returns {@code -1} if the combo is unknown or empty.
	 */
	public int resolveRestoreItem(String name)
	{
		ComboGroup group = ComboStore.cachedGet(plugin.configManager, plugin.gson, name);
		if (group == null || group.members.isEmpty())
		{
			return -1;
		}
		Map<Integer, Integer> byBase = bankItemsByBasePresent();
		Map<Integer, Integer> byVariant = bankItemsByVariantPresent();
		for (Integer base : group.members)
		{
			List<Integer> order = group.variantOrder == null ? null : group.variantOrder.get(base);
			if (order != null)
			{
				for (Integer variant : order)
				{
					Integer actual = byVariant.get(plugin.itemManager.canonicalize(variant));
					if (actual != null)
					{
						return actual;
					}
				}
			}
			Integer actual = byBase.get(ItemIndex.canonicalBase(base));
			if (actual != null)
			{
				return actual;
			}
		}
		int goal = group.displayIconId();
		return goal > 0 ? goal : -1;
	}

	/** Whether a real (non-placeholder, qty&gt;0) copy of the given item is currently in the bank. */
	public boolean isOwnedReal(int itemId)
	{
		Map<Integer, Integer> byBase = bankItemsByBase(); // also ensures the stat-duplicate merge map is built
		int base = ItemIndex.comboBaseOf(plugin.itemManager, itemId); // shared base definition (see ItemIndex.comboBaseOf)
		return byBase.containsKey(base);
	}

	/**
	 * A group's member base ids in priority order (the manual list order), canonicalized to their
	 * stat-duplicate roots so callers comparing tab/bank item bases line up. Used for membership/scrub
	 * comparison sets — NOT for variant display (which keys off the raw stored base).
	 */
	public List<Integer> orderedMemberBases(String name)
	{
		// READ-ONLY: only reads group.members (copied into a fresh list below), so the cached snapshot is safe.
		ComboGroup group = ComboStore.cachedGet(plugin.configManager, plugin.gson, name);
		if (group == null)
		{
			return new ArrayList<>();
		}
		Set<Integer> shared = sharedBases(name);
		List<Integer> bases = new ArrayList<>(group.members.size());
		for (int base : group.members)
		{
			int canon = ItemIndex.canonicalBase(base);
			if (!shared.contains(canon)) // a contested (shared) base is left unmanaged: not a member for scrub/placement
			{
				bases.add(canon);
			}
		}
		return bases;
	}

	/**
	 * Canonical bases of {@code comboName} that are SHARED with at least one other combo in the same non-empty
	 * category, and so are excluded from winner resolution and membership. Empty for an ungrouped combo or one
	 * whose items are unique within its group. Cached against the combos-JSON (auto-refreshes on any combo edit).
	 */
	public Set<Integer> sharedBases(String comboName)
	{
		String json = plugin.configManager.getConfiguration(ComboTagsPlugin.CONFIG_GROUP, ComboStore.CONFIG_KEY);
		String key = json == null ? "" : json;
		Map<String, Set<Integer>> cache = sharedBasesByCombo;
		if (cache == null || !key.equals(sharedCacheJson))
		{
			cache = computeSharedBases();
			sharedBasesByCombo = cache;
			sharedCacheJson = key;
		}
		return cache.getOrDefault(comboName, Collections.emptySet());
	}

	/** Builds {@code comboName -> shared canonical bases} by counting, per category, how many combos hold each base. */
	private Map<String, Set<Integer>> computeSharedBases()
	{
		List<ComboGroup> all = ComboStore.cachedAll(plugin.configManager, plugin.gson);
		// Per non-empty category: canonical base -> number of distinct combos that contain it.
		Map<String, Map<Integer, Integer>> countByCat = new HashMap<>();
		for (ComboGroup g : all)
		{
			if (g.category == null || g.category.isEmpty())
			{
				continue;
			}
			Map<Integer, Integer> counts = countByCat.computeIfAbsent(g.category, k -> new HashMap<>());
			Set<Integer> seen = new HashSet<>(); // a single combo listing an item twice must not self-conflict
			for (int base : g.members)
			{
				int canon = ItemIndex.canonicalBase(base);
				if (seen.add(canon))
				{
					counts.merge(canon, 1, Integer::sum);
				}
			}
		}
		Map<String, Set<Integer>> result = new HashMap<>();
		for (ComboGroup g : all)
		{
			if (g.category == null || g.category.isEmpty())
			{
				continue;
			}
			Map<Integer, Integer> counts = countByCat.get(g.category);
			Set<Integer> shared = new HashSet<>();
			for (int base : g.members)
			{
				int canon = ItemIndex.canonicalBase(base);
				if (counts.getOrDefault(canon, 0) >= 2)
				{
					shared.add(canon);
				}
			}
			if (!shared.isEmpty())
			{
				result.put(g.name, shared);
			}
		}
		return result;
	}

	/** Maps base id → an actual item id currently in the bank (excludes empty slots and placeholders). */
	private Map<Integer, Integer> bankItemsByBase()
	{
		ensureBankSnapshot();
		return bankByBaseCache != null ? bankByBaseCache : new HashMap<>();
	}

	/** Maps {@code canonicalize(id)} → an actual bank item id, distinguishing variants that share a base. */
	private Map<Integer, Integer> bankItemsByVariant()
	{
		ensureBankSnapshot();
		return bankByVariantCache != null ? bankByVariantCache : new HashMap<>();
	}

	/** Like {@link #bankItemsByBase} but also counting leftover bank placeholders (for restore-on-delete). */
	private Map<Integer, Integer> bankItemsByBasePresent()
	{
		ensureBankSnapshot();
		return bankByBasePresentCache != null ? bankByBasePresentCache : new HashMap<>();
	}

	/** Like {@link #bankItemsByVariant} but also counting leftover bank placeholders (for restore-on-delete). */
	private Map<Integer, Integer> bankItemsByVariantPresent()
	{
		ensureBankSnapshot();
		return bankByVariantPresentCache != null ? bankByVariantPresentCache : new HashMap<>();
	}

	/** Builds both bank snapshots (base-level and variant-level) once, until the next {@link #invalidateBankCache}. */
	private void ensureBankSnapshot()
	{
		if (bankByBaseCache != null)
		{
			return;
		}
		// Ensure the stat-duplicate merge map exists so cosmetic recolors (e.g. Sanguine Torva) key to the
		// same base as their member; no-op once built. Safe here — the resolver is client-thread only.
		ItemIndex.build(plugin.client, plugin.itemManager);
		ItemContainer bank = plugin.client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			// The bank just isn't loaded yet (no ItemContainerChanged to invalidate on) → don't cache; retry later.
			return;
		}
		Map<Integer, Integer> byBase = new HashMap<>();          // real, owned items only (drives cell display)
		Map<Integer, Integer> byVariant = new HashMap<>();
		Map<Integer, Integer> byBasePresent = new HashMap<>();   // + bank placeholders, keyed to their real item
		Map<Integer, Integer> byVariantPresent = new HashMap<>();
		for (Item item : bank.getItems())
		{
			int id = item.getId();
			if (id < 0)
			{
				continue;
			}
			boolean placeholder = plugin.isPlaceholder(id);
			// The real item this slot represents: itself, or the item a leftover bank placeholder stands for.
			int realId = placeholder ? plugin.itemManager.getItemComposition(id).getPlaceholderId() : id;
			if (!placeholder && item.getQuantity() <= 0)
			{
				continue; // genuinely empty slot
			}
			if (realId <= 0)
			{
				continue;
			}
			int canon = plugin.itemManager.canonicalize(realId);
			int base = ItemIndex.comboBaseOf(plugin.itemManager, realId);
			byVariantPresent.putIfAbsent(canon, realId);
			byBasePresent.putIfAbsent(base, realId);
			// A placeholder (count 0) means you don't actually own it → excluded from the cell-display maps.
			if (!placeholder)
			{
				byVariant.putIfAbsent(canon, realId);
				byBase.putIfAbsent(base, realId);
			}
		}
		bankByVariantCache = byVariant;
		bankByBaseCache = byBase;
		bankByVariantPresentCache = byVariantPresent;
		bankByBasePresentCache = byBasePresent;
	}
}

package com.combotags;

import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Data;
import net.runelite.client.config.ConfigManager;

/**
 * Persistence for combo "smart cells" embedded in host bank tabs. Each host tab can have any number
 * of cells, each backed by a combo group; the cell holds that group's current winner as a real,
 * tagged item, kept in sync on render.
 *
 * <p>Stored under {@link ComboTagsPlugin#CONFIG_GROUP} at {@code comboslots_<hostTag>} as a CSV
 * of {@code index:group} entries (combo group names contain no commas or colons). The displayed winner
 * is NOT stored — it is resolved live from the bank at render time and the real widget is surfaced (or a
 * ghost drawn), so nothing is tagged/untagged. Old {@code index:group:placedItem} rows are still read
 * (the trailing field is ignored).
 */
public final class ComboSlots
{
	public static final String CONFIG_KEY_PREFIX = "comboslots_";

	/** One embedded combo cell: where it sits in the host tab and which combo group it shows. */
	@Data
	@AllArgsConstructor
	public static final class Slot
	{
		private int index;            // layout index in the host tab
		private final String group;   // combo group name (e.g. "[MeleeLegs]")
	}

	private ComboSlots()
	{
	}

	public static List<Slot> read(ConfigManager configManager, String hostTag)
	{
		// New format: index:group. Old format: index:group:placedItem (placedItem ignored — parts[1] is the group).
		return ComboCsv.read(configManager, CONFIG_KEY_PREFIX + hostTag, (index, parts) -> new Slot(index, parts[1].trim()));
	}

	public static void write(ConfigManager configManager, String hostTag, List<Slot> slots)
	{
		List<String> rows = new ArrayList<>();
		for (Slot s : slots)
		{
			rows.add(s.getIndex() + ":" + s.getGroup());
		}
		ComboCsv.write(configManager, CONFIG_KEY_PREFIX + hostTag, rows);
	}
}

package com.combotags;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Loads/saves combo groups as a single JSON array under {@code combotags.combos}. One source of
 * truth for a group's members, order, rank stat, color, and variant picks.
 */
@Slf4j
public final class ComboStore
{
	public static final String CONFIG_KEY = "combos";
	public static final String CATEGORIES_KEY = "combo_categories";
	public static final String CATEGORY_ORDER_KEY = "combo_category_order";
	public static final String UNGROUPED_COLLAPSED_KEY = "combo_ungrouped_collapsed";
	private static final Type LIST_TYPE = new TypeToken<List<ComboGroup>>()
	{
	}.getType();
	private static final Type CAT_LIST_TYPE = new TypeToken<List<ComboCategory>>()
	{
	}.getType();
	private static final Type STRING_LIST_TYPE = new TypeToken<List<String>>()
	{
	}.getType();

	// Parse cache for the hot READ-ONLY path (resolver: per cell, per bank build). Keyed on the EXACT JSON
	// config string; any save writes a new string, so the key mismatches and we transparently re-parse — no
	// external invalidation needed. Published together under a synchronized block. The cached list/objects are
	// SHARED and treated as read-only by callers; mutating callers must keep using all() (a fresh parse).
	private static volatile String cachedJson;
	private static volatile List<ComboGroup> cachedList;

	private ComboStore()
	{
	}

	public static List<ComboGroup> all(ConfigManager configManager, Gson gson)
	{
		String json = configManager.getConfiguration(ComboTagsPlugin.CONFIG_GROUP, CONFIG_KEY);
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			List<ComboGroup> list = gson.fromJson(json, LIST_TYPE);
			if (list == null)
			{
				return new ArrayList<>();
			}
			list.forEach(ComboGroup::normalize);
			return list;
		}
		catch (Exception ex)
		{
			log.warn("failed to parse combo groups json", ex);
			return new ArrayList<>();
		}
	}

	public static ComboGroup get(ConfigManager configManager, Gson gson, String name)
	{
		for (ComboGroup g : all(configManager, gson))
		{
			if (g.name.equals(name))
			{
				return g;
			}
		}
		return null;
	}

	/**
	 * A SHARED, READ-ONLY snapshot of all groups, reusing a cached parse while the JSON config string is
	 * unchanged (auto-invalidated on any save, which writes a new string). For the hot resolver path that
	 * re-reads the same config many times per bank build. Never mutate the returned list or its groups —
	 * mutation paths (upsert/moveCombo/delete/deleteCategory) must use {@link #all} for a fresh parse.
	 */
	public static synchronized List<ComboGroup> cachedAll(ConfigManager configManager, Gson gson)
	{
		String json = configManager.getConfiguration(ComboTagsPlugin.CONFIG_GROUP, CONFIG_KEY);
		// Match all()'s no-op handling: null/empty json → empty list. Cache it too so empty configs don't re-key.
		String key = json == null ? "" : json;
		if (cachedList != null && key.equals(cachedJson))
		{
			return cachedList;
		}
		List<ComboGroup> parsed = all(configManager, gson); // reuse all()'s parse + normalize + failure handling
		// Publish key and list together (this method is synchronized; fields are volatile for off-thread readers).
		cachedJson = key;
		cachedList = parsed;
		return parsed;
	}

	/**
	 * READ-ONLY lookup of a single group by name from {@link #cachedAll}. The returned group is shared and
	 * must not be mutated; use {@link #get} + {@link #upsert} for edits.
	 */
	public static ComboGroup cachedGet(ConfigManager configManager, Gson gson, String name)
	{
		for (ComboGroup g : cachedAll(configManager, gson))
		{
			if (g.name.equals(name))
			{
				return g;
			}
		}
		return null;
	}

	public static List<String> names(ConfigManager configManager, Gson gson)
	{
		List<String> names = new ArrayList<>();
		for (ComboGroup g : all(configManager, gson))
		{
			names.add(g.name);
		}
		return names;
	}

	public static void save(ConfigManager configManager, Gson gson, List<ComboGroup> groups)
	{
		configManager.setConfiguration(ComboTagsPlugin.CONFIG_GROUP, CONFIG_KEY, gson.toJson(groups, LIST_TYPE));
	}

	/** Inserts or replaces a group (matched by name), preserving its position so editing never reorders it. */
	public static void upsert(ConfigManager configManager, Gson gson, ComboGroup group)
	{
		List<ComboGroup> list = all(configManager, gson);
		int idx = -1;
		for (int i = 0; i < list.size(); i++)
		{
			if (list.get(i).name.equals(group.name))
			{
				idx = i;
				break;
			}
		}
		if (idx >= 0)
		{
			list.set(idx, group);
		}
		else
		{
			list.add(group);
		}
		save(configManager, gson, list);
	}

	/**
	 * Moves a combo up (delta -1) or down (delta +1) relative to the other combos in its OWN section
	 * (same category, or the ungrouped section). Other sections are unaffected.
	 */
	public static void moveCombo(ConfigManager configManager, Gson gson, String name, int delta)
	{
		List<ComboGroup> list = all(configManager, gson);
		int i = -1;
		for (int k = 0; k < list.size(); k++)
		{
			if (list.get(k).name.equals(name))
			{
				i = k;
				break;
			}
		}
		if (i < 0)
		{
			return;
		}
		String cat = norm(list.get(i).category);
		int step = delta < 0 ? -1 : 1;
		int j = -1;
		for (int k = i + step; k >= 0 && k < list.size(); k += step)
		{
			if (norm(list.get(k).category).equals(cat))
			{
				j = k; // nearest sibling in that direction
				break;
			}
		}
		if (j < 0)
		{
			return;
		}
		Collections.swap(list, i, j);
		save(configManager, gson, list);
	}

	private static String norm(String s)
	{
		return s == null ? "" : s;
	}

	public static void delete(ConfigManager configManager, Gson gson, String name)
	{
		List<ComboGroup> list = all(configManager, gson);
		if (list.removeIf(g -> g.name.equals(name)))
		{
			save(configManager, gson, list);
		}
	}

	// ---- categories ----

	public static List<ComboCategory> categories(ConfigManager configManager, Gson gson)
	{
		String json = configManager.getConfiguration(ComboTagsPlugin.CONFIG_GROUP, CATEGORIES_KEY);
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			List<ComboCategory> list = gson.fromJson(json, CAT_LIST_TYPE);
			return list != null ? list : new ArrayList<>();
		}
		catch (Exception ex)
		{
			log.warn("failed to parse combo categories json", ex);
			return new ArrayList<>();
		}
	}

	public static ComboCategory category(ConfigManager configManager, Gson gson, String name)
	{
		for (ComboCategory c : categories(configManager, gson))
		{
			if (c.name.equals(name))
			{
				return c;
			}
		}
		return null;
	}

	public static void saveCategories(ConfigManager configManager, Gson gson, List<ComboCategory> categories)
	{
		configManager.setConfiguration(ComboTagsPlugin.CONFIG_GROUP, CATEGORIES_KEY, gson.toJson(categories, CAT_LIST_TYPE));
	}

	public static void upsertCategory(ConfigManager configManager, Gson gson, ComboCategory category)
	{
		List<ComboCategory> list = categories(configManager, gson);
		// Replace in place so editing (e.g. collapse toggle) never reshuffles the stored list.
		int idx = -1;
		for (int i = 0; i < list.size(); i++)
		{
			if (list.get(i).name.equals(category.name))
			{
				idx = i;
				break;
			}
		}
		if (idx >= 0)
		{
			list.set(idx, category);
		}
		else
		{
			list.add(category);
		}
		saveCategories(configManager, gson, list);
	}

	// ---- category display order (stored separately so editing a category never moves it) ----

	public static List<String> categoryOrder(ConfigManager configManager, Gson gson)
	{
		String json = configManager.getConfiguration(ComboTagsPlugin.CONFIG_GROUP, CATEGORY_ORDER_KEY);
		if (json == null || json.isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			List<String> list = gson.fromJson(json, STRING_LIST_TYPE);
			return list != null ? list : new ArrayList<>();
		}
		catch (Exception ex)
		{
			log.warn("failed to parse combo category order json", ex);
			return new ArrayList<>();
		}
	}

	public static void saveCategoryOrder(ConfigManager configManager, Gson gson, List<String> order)
	{
		configManager.setConfiguration(ComboTagsPlugin.CONFIG_GROUP, CATEGORY_ORDER_KEY, gson.toJson(order, STRING_LIST_TYPE));
	}

	/**
	 * Categories sorted by the saved order; appends any newly-seen names and drops stale ones.
	 * Pure read: reconciles the order IN-MEMORY only and never persists (no ConfigManager write),
	 * so it is safe to call during an EDT panel rebuild without triggering a ConfigChanged feedback loop.
	 * The saved order is repaired by the explicit reorder paths instead.
	 */
	public static List<ComboCategory> orderedCategories(ConfigManager configManager, Gson gson)
	{
		List<ComboCategory> cats = categories(configManager, gson);
		List<String> order = categoryOrder(configManager, gson);
		for (ComboCategory c : cats)
		{
			if (!order.contains(c.name))
			{
				order.add(c.name);
			}
		}
		order.removeIf(n -> cats.stream().noneMatch(c -> c.name.equals(n)));
		cats.sort(Comparator.comparingInt(c -> order.indexOf(c.name)));
		return cats;
	}

	/** Moves a category up (delta -1) or down (delta +1) in the saved order. */
	public static void moveCategory(ConfigManager configManager, Gson gson, String name, int delta)
	{
		List<String> order = categoryOrder(configManager, gson);
		// Make sure every existing category is represented before swapping.
		for (ComboCategory c : categories(configManager, gson))
		{
			if (!order.contains(c.name))
			{
				order.add(c.name);
			}
		}
		int i = order.indexOf(name);
		int j = i + delta;
		if (i < 0 || j < 0 || j >= order.size())
		{
			return;
		}
		Collections.swap(order, i, j);
		saveCategoryOrder(configManager, gson, order);
	}

	// ---- ungrouped section (a pseudo-category: collapsible, but no color/order/delete) ----

	public static boolean isUngroupedCollapsed(ConfigManager configManager)
	{
		return "true".equals(configManager.getConfiguration(ComboTagsPlugin.CONFIG_GROUP, UNGROUPED_COLLAPSED_KEY));
	}

	public static void setUngroupedCollapsed(ConfigManager configManager, boolean collapsed)
	{
		configManager.setConfiguration(ComboTagsPlugin.CONFIG_GROUP, UNGROUPED_COLLAPSED_KEY, Boolean.toString(collapsed));
	}

	public static void deleteCategory(ConfigManager configManager, Gson gson, String name)
	{
		List<ComboCategory> list = categories(configManager, gson);
		if (list.removeIf(c -> c.name.equals(name)))
		{
			saveCategories(configManager, gson, list);
		}
		// Un-file any combos that were in this category.
		List<ComboGroup> combos = all(configManager, gson);
		boolean changed = false;
		for (ComboGroup g : combos)
		{
			if (name.equals(g.category))
			{
				g.category = "";
				changed = true;
			}
		}
		if (changed)
		{
			save(configManager, gson, combos);
		}
	}

	/** Deletes a category AND every combo filed under it (vs {@link #deleteCategory}, which un-files them). */
	public static void deleteCategoryAndCombos(ConfigManager configManager, Gson gson, String name)
	{
		List<ComboCategory> cats = categories(configManager, gson);
		if (cats.removeIf(c -> c.name.equals(name)))
		{
			saveCategories(configManager, gson, cats);
		}
		List<ComboGroup> combos = all(configManager, gson);
		if (combos.removeIf(g -> name.equals(g.category)))
		{
			save(configManager, gson, combos);
		}
	}
}

